import assert from 'node:assert/strict';
import { Readable } from 'node:stream';
import { after, test } from 'node:test';
import type { PinnedHttpsTransport } from '../../src/administration/adminPinnedHttps';
import { MetadataLookupSourceError, type LookupGateMode } from '../../src/administration/lookup/lookupContract';
import type { LookupGateLease, MetadataLookupRateGate } from '../../src/administration/lookup/lookupRateGate';
import { createLookupResponseCache, type LookupResponseCache } from '../../src/administration/lookup/lookupResponseCache';
import { requestLookupJson, type LookupClientDependencies, type LookupJsonRequest } from '../../src/administration/lookup/lookupSourceRequest';
import { musicBrainzDestination } from '../../src/administration/lookup/musicBrainzClient';
import { availableLookupConfiguration, fixtureAddress, fixtureTransport, type LookupExchange } from '../support/metadataLookupFixtures';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

const target = 'https://musicbrainz.org/ws/2/release/00000000-0000-4000-8000-0000000000a1?fmt=json';
const answer = (status: number, headers: Record<string, string | null>, body: unknown = { ok: true }): LookupExchange =>
    typeof body === 'string' ? { url: target, status, headers, bodyText: body } : { url: target, status, headers, body };
const lookupRequest = (overrides: Partial<LookupJsonRequest<unknown>> = {}): LookupJsonRequest<unknown> => ({
    source: 'musicbrainz', url: new URL(target), destination: musicBrainzDestination, accept: 'application/json',
    contentTypes: ['application/json'], maximumBytes: 4096, deadlineMs: 5000, rateLimitStatuses: [429, 503],
    // The complete parser builds prototype-less objects; a JSON round trip makes them comparable.
    emptyStatuses: [404], emptyValue: null, parse: value => ({ parsed: JSON.parse(JSON.stringify(value)) }), ...overrides
});

type GateRecord = { acquisitions: number; releases: ({ backoffMs?: number } | undefined)[] };
type Harness = { gate: GateRecord; sets: string[]; sleeps: number[]; dependencies: LookupClientDependencies };
const harnesses: Harness[] = [];
/** Real request path with a counting gate, a recording cache and an instant sleep. */
const harness = (transport: PinnedHttpsTransport, overrides: Partial<LookupClientDependencies> = {}): Harness => {
    // Pacing is the gate's own concern (tested elsewhere); here every slot is granted at once and the
    // spy records the backoff each release pushes.
    const inner: MetadataLookupRateGate = { acquire: async () => ({ release: async () => undefined }) };
    const record = { acquisitions: 0, releases: [] as ({ backoffMs?: number } | undefined)[] };
    const gate: MetadataLookupRateGate = {
        async acquire(source, mode, signal) {
            record.acquisitions++;
            const lease = await inner.acquire(source, mode, signal);
            return { release: async outcome => { record.releases.push(outcome); await lease.release(outcome); } } satisfies LookupGateLease;
        }
    };
    const cached = createLookupResponseCache();
    const sets: string[] = [];
    const cache: LookupResponseCache = { get: key => cached.get(key), set: (key, value, bytes) => { sets.push(key); cached.set(key, value, bytes); }, clear: () => cached.clear() };
    const sleeps: number[] = [];
    const dependencies: LookupClientDependencies = {
        gate, transport, cache, configuration: availableLookupConfiguration, sleep: async ms => { sleeps.push(ms); }, ...overrides
    };
    const created = { gate: record, sets, sleeps, dependencies };
    harnesses.push(created);
    return created;
};
const run = (current: Harness, request = lookupRequest(), mode: LookupGateMode = 'wait', signal = new AbortController().signal) =>
    requestLookupJson(request, { mode, signal }, current.dependencies);
const failure = (kind: string) => (error: unknown) => {
    assert.ok(error instanceof MetadataLookupSourceError, String(error));
    assert.equal(error.source, 'musicbrainz'); assert.equal(error.failure, kind);
    assert.match(error.message, /^METADATA_LOOKUP_[A-Z_]+$/, 'the message is a bounded code without a URL, header or body');
    return true;
};

/** A transport that never answers at the chosen stage; the body stage serves a 200 whose body never ends. */
const stalled = (stage: 'lookup' | 'request' | 'body') => {
    const state = { lookups: 0, requests: 0, body: undefined as Readable | undefined };
    const transport: PinnedHttpsTransport = {
        lookup: () => { state.lookups++; return stage === 'lookup' ? new Promise(() => undefined) : Promise.resolve([fixtureAddress]); },
        request: () => {
            state.requests++;
            if (stage === 'request') return new Promise(() => undefined);
            state.body = new Readable({ read() { /* never ends */ } });
            state.body.push('{');
            return Promise.resolve({ statusCode: 200, headers: { 'content-type': 'application/json' }, body: state.body });
        }
    };
    return { transport, state };
};
/** `AbortSignal.timeout` timers do not hold the event loop open, so stalled-transport tests hold it themselves. */
const holdingEventLoop = async (work: () => Promise<void>) => {
    const keepAlive = setTimeout(() => undefined, 10_000);
    try { await work(); } finally { clearTimeout(keepAlive); }
};

test('a caller abort before or during DNS, the request, the body or the retry wait is cancelled and releases its lease', () => holdingEventLoop(async () => {
    const aborted = new AbortController(); aborted.abort();
    const idle = harness(fixtureTransport([]).transport);
    await assert.rejects(run(idle, lookupRequest(), 'wait', aborted.signal), failure('cancelled'));
    assert.equal(idle.gate.acquisitions, 0, 'a pre-aborted call never takes a gate slot');

    for (const stage of ['lookup', 'request', 'body'] as const) {
        const fake = stalled(stage);
        const current = harness(fake.transport);
        const controller = new AbortController();
        const pending = run(current, lookupRequest(), 'wait', controller.signal);
        setTimeout(() => controller.abort(), 20);
        await assert.rejects(pending, failure('cancelled'), stage);
        assert.equal(current.gate.acquisitions, 1, stage); assert.deepEqual(current.gate.releases, [undefined], stage);
        assert.deepEqual(current.sleeps, [], stage); assert.deepEqual(current.sets, [], stage);
        assert.equal(fake.state.requests, stage === 'lookup' ? 0 : 1, stage);
        if (stage === 'body') assert.equal(fake.state.body!.destroyed, true, 'the unfinished body is destroyed');
    }

    const controller = new AbortController();
    const fake = fixtureTransport([answer(503, { 'content-type': 'text/html', 'retry-after': '1' }, 'busy')]);
    const waiting = harness(fake.transport, { sleep: async (_ms, signal) => { controller.abort(); signal.throwIfAborted(); } });
    await assert.rejects(run(waiting, lookupRequest(), 'wait', controller.signal), failure('cancelled'));
    assert.equal(fake.requests.length, 1); assert.deepEqual(waiting.gate.releases, [{ backoffMs: 1000 }], 'the Retry-After still reaches the gate');
}));

test('the request deadline ends a stalled source as unavailable, without an in-call retry', () => holdingEventLoop(async () => {
    for (const stage of ['lookup', 'request', 'body'] as const) {
        const fake = stalled(stage);
        const current = harness(fake.transport);
        const started = Date.now();
        await assert.rejects(run(current, lookupRequest({ deadlineMs: 30 })), failure('unavailable'), stage);
        assert.ok(Date.now() - started < 2000, `${stage} ended at the deadline`);
        assert.equal(current.gate.acquisitions, 1, stage); assert.equal(current.gate.releases.length, 1, stage);
        assert.deepEqual(current.sleeps, [], stage); assert.deepEqual(current.sets, [], stage);
        if (stage === 'body') assert.equal(fake.state.body!.destroyed, true);
    }
}));

test('DNS, connection and unexpected statuses are unavailable after one attempt and are never cached', async () => {
    const dnsFailure = harness({
        lookup: async () => { throw Object.assign(new Error('getaddrinfo ENOTFOUND musicbrainz.org'), { code: 'ENOTFOUND' }); },
        request: async () => assert.fail('no request after a DNS failure')
    });
    await assert.rejects(run(dnsFailure), failure('unavailable'));
    const resetFailure = harness({ lookup: async () => [fixtureAddress], request: async () => { throw new Error(`ECONNRESET ${target}`); } });
    await assert.rejects(run(resetFailure), failure('unavailable'));
    const privateAnswer = harness({ lookup: async () => [{ address: '10.0.0.1', family: 4 }], request: async () => assert.fail('a private answer is never connected') });
    await assert.rejects(run(privateAnswer), failure('unavailable'));
    for (const current of [dnsFailure, resetFailure, privateAnswer]) {
        assert.equal(current.gate.acquisitions, 1); assert.deepEqual(current.sleeps, []); assert.deepEqual(current.sets, []);
    }

    for (const [status, emptyStatuses] of [[500, [404]], [502, [404]], [400, [404]], [401, [404]], [304, [404]], [404, []], [410, [404]]] as const) {
        const fake = fixtureTransport([answer(status, { 'content-type': 'text/html' }, 'error page')]);
        const current = harness(fake.transport);
        await assert.rejects(run(current, lookupRequest({ emptyStatuses })), failure('unavailable'), String(status));
        assert.equal(fake.requests.length, 1, String(status)); assert.deepEqual(current.sleeps, [], String(status));
        assert.deepEqual(current.sets, [], String(status)); assert.equal(fake.bodies[0].destroyed, true, String(status));
    }
    const noLocation = fixtureTransport([answer(302, { 'content-type': 'text/html' }, 'moved')]);
    await assert.rejects(run(harness(noLocation.transport)), failure('unavailable'));
    assert.equal(noLocation.requests.length, 1);
});

test('a 200 answer needs an allowlisted content type with at most a UTF-8 charset and an identity encoding', async () => {
    const accepted: Record<string, string>[] = [
        { 'content-type': 'application/json' }, { 'content-type': 'application/json; charset=utf-8' },
        { 'content-type': 'Application/JSON;charset="UTF-8"' }, { 'content-type': 'application/json', 'content-encoding': 'identity' }
    ];
    for (const headers of accepted) {
        const current = harness(fixtureTransport([answer(200, headers)]).transport);
        assert.deepEqual(await run(current), { parsed: { ok: true } }, JSON.stringify(headers));
        assert.equal(current.sets.length, 1);
    }
    const refused: Record<string, string | null>[] = [
        { 'content-type': null }, { 'content-type': 'application/json; charset=iso-8859-1' }, { 'content-type': 'application/json; boundary=x' },
        { 'content-type': 'application/json; charset=utf-8; q=1' }, { 'content-type': 'application/jsonp' }, { 'content-type': 'text/javascript' },
        { 'content-type': 'text/html; charset=utf-8' }, { 'content-type': 'application/json', 'content-encoding': 'gzip' },
        { 'content-type': 'application/json', 'content-encoding': 'br' }, { 'content-type': 'application/json', 'content-encoding': 'identity, gzip' }
    ];
    for (const headers of refused) {
        const fake = fixtureTransport([answer(200, headers)]);
        const current = harness(fake.transport);
        await assert.rejects(run(current), failure('invalidResponse'), JSON.stringify(headers));
        assert.deepEqual(current.sets, [], JSON.stringify(headers)); assert.equal(fake.bodies[0].destroyed, true, JSON.stringify(headers));
        assert.deepEqual(current.sleeps, []); assert.equal(current.gate.acquisitions, 1);
    }
    const parseFailure = harness(fixtureTransport([answer(200, { 'content-type': 'application/json' })]).transport);
    await assert.rejects(run(parseFailure, lookupRequest({ parse: () => { throw new Error(`unexpected field at ${target}`); } })), failure('invalidResponse'));
    assert.deepEqual(parseFailure.sets, []);
});

test('429 is rate limited like 503; an HTTP-date Retry-After sets the backoff and an unusable one falls back to the schedule', async () => {
    const now = Date.parse('Sun, 18 Oct 2026 10:00:00 GMT');
    const fake = fixtureTransport([
        answer(429, { 'content-type': 'text/html', 'retry-after': 'Sun, 18 Oct 2026 10:00:07 GMT' }, 'slow down'),
        answer(503, { 'content-type': 'text/html', 'retry-after': 'soon' }, 'busy'),
        answer(200, { 'content-type': 'application/json' })
    ]);
    const current = harness(fake.transport, { now: () => now });
    assert.deepEqual(await run(current), { parsed: { ok: true } });
    assert.deepEqual(current.sleeps, [7000, 5000]);
    assert.deepEqual(current.gate.releases, [{ backoffMs: 7000 }, { backoffMs: 5000 }, undefined]);
    assert.equal(fake.requests.length, 3); assert.ok(fake.bodies.slice(0, 2).every(body => body.destroyed));
});

test('a gate refusal propagates unchanged and nothing is resolved or sent', async () => {
    for (const refusal of ['busy', 'unavailable', 'cancelled'] as const) {
        const fake = fixtureTransport([answer(200, { 'content-type': 'application/json' })]);
        const gate: MetadataLookupRateGate = { acquire: async source => { throw new MetadataLookupSourceError(source, refusal, refusal === 'busy' ? 1234 : null); } };
        const current = harness(fake.transport, { gate });
        await assert.rejects(run(current, lookupRequest(), 'busy'), error => {
            failure(refusal)(error);
            assert.equal((error as MetadataLookupSourceError).retryAfterMs, refusal === 'busy' ? 1234 : null); return true;
        });
        assert.deepEqual(fake.lookups, []); assert.deepEqual(fake.requests, []); assert.deepEqual(current.sets, []);
    }
});

test('cached answers are deep-frozen, shared by reference and keyed by source and exact URL', async () => {
    const other = `${target}&limit=1`;
    const fake = fixtureTransport([answer(200, { 'content-type': 'application/json' }, { nested: { list: [1] } }),
        { ...answer(200, { 'content-type': 'application/json' }), url: other }]);
    const current = harness(fake.transport);
    const first = await run(current) as { parsed: { nested: { list: number[] } } };
    const second = await run(current);
    assert.equal(second, first, 'a hit returns the stored value itself');
    assert.ok(Object.isFrozen(first) && Object.isFrozen(first.parsed.nested) && Object.isFrozen(first.parsed.nested.list));
    await run(current, lookupRequest({ url: new URL(other) }));
    assert.deepEqual(fake.requests.map(request => request.url), [target, other]);
    assert.deepEqual(current.sets, [`musicbrainz ${target}`, `musicbrainz ${other}`]);

    const cache = createLookupResponseCache({ maxEntries: 0 });
    cache.set('a', 1, 1); assert.equal(cache.get('a'), undefined, 'a zero-entry cache stores nothing');
    const bounded = createLookupResponseCache({ maxBytes: 10 });
    bounded.set('nan', 1, Number.NaN); bounded.set('infinite', 1, Number.POSITIVE_INFINITY);
    assert.equal(bounded.get('nan'), undefined); assert.equal(bounded.get('infinite'), undefined);
    bounded.set('a', 1, 6); bounded.set('a', 2, 6); bounded.set('b', 3, 4);
    assert.deepEqual([bounded.get('a'), bounded.get('b')], [{ value: 2 }, { value: 3 }], 'replacing a key releases its old byte count');
});

test('every call in this file released exactly the leases it acquired', () => {
    // Runs last, so it sees every harness the tests above created.
    assert.ok(harnesses.length > 20);
    for (const current of harnesses) assert.equal(current.gate.releases.length, current.gate.acquisitions);
});
